[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ScreenVault — UI & UX design inspiration for mobile & web apps</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --primary: #2563EB;
      --primary-light: #3B82F6;
      --primary-dark: #1D4ED8;
      --bg: #FFFFFF;
      --bg-secondary: #F8FAFC;
      --surface: #F5F5F5;
      --text: #1E293B;
      --text-secondary: #64748B;
      --text-muted: #94A3B8;
      --border: #E2E8F0;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --radius-sm: 6px;
      --radius: 10px;
      --radius-lg: 16px;
      --radius-full: 9999px;
      --transition: 200ms ease;
      --transition-slow: 300ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--text);
      background: var(--bg);
      -webkit-font-smoothing: antialiased;
    }

    /* Utility Classes */
    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .container-narrow {
      max-width: 800px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Announcement Bar */
    .announcement {
      background: var(--primary);
      color: white;
      text-align: center;
      padding: 10px 24px;
      font-size: 14px;
      font-weight: 500;
      letter-spacing: -0.01em;
    }

    .announcement a {
      color: inherit;
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    /* Navigation */
    .nav {
      position: sticky;
      top: 0;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--border);
      z-index: 100;
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .nav-logo {
      font-size: 20px;
      font-weight: 700;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.03em;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-link {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition);
      cursor: pointer;
    }

    .nav-link:hover {
      color: var(--text);
    }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      border-radius: var(--radius-sm);
      text-decoration: none;
      cursor: pointer;
      transition: all var(--transition);
      border: none;
      font-family: inherit;
    }

    .btn-primary {
      background: var(--primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text);
    }

    .btn-secondary:hover {
      background: var(--surface);
    }

    .btn-ghost {
      background: transparent;
      color: var(--text-secondary);
    }

    .btn-ghost:hover {
      color: var(--text);
      background: var(--surface);
    }

    .btn-lg {
      padding: 14px 28px;
      font-size: 16px;
    }

    /* Hero Section */
    .hero {
      padding: 80px 0 100px;
      text-align: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 14px;
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      margin-bottom: 24px;
    }

    .hero-badge-dot {
      width: 6px;
      height: 6px;
      background: #22C55E;
      border-radius: 50%;
    }

    .hero h1 {
      font-size: clamp(36px, 6vw, 56px);
      font-weight: 700;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
      color: var(--text);
    }

    .hero-subtitle {
      font-size: clamp(18px, 2.5vw, 20px);
      color: var(--text-secondary);
      margin-bottom: 40px;
      max-width: 560px;
      margin-left: auto;
      margin-right: auto;
    }

    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .hero-note {
      font-size: 13px;
      color: var(--text-muted);
      margin-top: 16px;
    }

    /* Trusted By Section */
    .trusted {
      padding: 48px 0;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      background: var(--bg-secondary);
    }

    .trusted-label {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-muted);
      text-align: center;
      margin-bottom: 24px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .trusted-logos {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 48px;
      flex-wrap: wrap;
    }

    .trusted-logo {
      font-size: 16px;
      font-weight: 600;
      color: var(--text-muted);
      opacity: 0.7;
      transition: opacity var(--transition);
    }

    .trusted-logo:hover {
      opacity: 1;
    }

    /* Stats Section */
    .stats {
      padding: 80px 0;
      background: var(--bg);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      text-align: center;
    }

    .stat-item {
      padding: 24px;
    }

    .stat-number {
      font-size: clamp(40px, 6vw, 56px);
      font-weight: 700;
      color: var(--primary);
      letter-spacing: -0.03em;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 16px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    /* Section Headers */
    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 40px);
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
    }

    .section-header p {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto;
    }

    /* Search Features Section */
    .features-search {
      padding: 80px 0;
      background: var(--bg-secondary);
    }

    .search-tabs {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .search-tab {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-secondary);
      background: transparent;
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
    }

    .search-tab:hover {
      border-color: var(--primary);
      color: var(--primary);
    }

    .search-tab.active {
      background: var(--primary);
      border-color: var(--primary);
      color: white;
    }

    .filter-pills {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-bottom: 40px;
      flex-wrap: wrap;
      padding: 0 16px;
    }

    .filter-pill {
      padding: 8px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition);
      white-space: nowrap;
      font-family: inherit;
    }

    .filter-pill:hover {
      border-color: var(--primary-light);
      color: var(--primary);
    }

    .filter-pill.active {
      background: var(--primary);
      border-color: var(--primary);
      color: white;
    }

    .screenshot-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 16px;
    }

    .screenshot-card {
      aspect-ratio: 9/19.5;
      background: var(--surface);
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--border);
      transition: all var(--transition);
    }

    .screenshot-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .screenshot-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .screenshot-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--surface) 0%, var(--border) 100%);
      color: var(--text-muted);
      font-size: 12px;
    }

    /* Feature Content Areas */
    .feature-content {
      display: none;
    }

    .feature-content.active {
      display: block;
    }

    /* Flows Section */
    .features-flows {
      padding: 80px 0;
      background: var(--bg);
    }

    .flows-toggle {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      background: var(--surface);
      border-radius: var(--radius-full);
      padding: 4px;
      width: fit-content;
      margin: 0 auto 48px;
    }

    .flows-toggle-btn {
      padding: 10px 24px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text-secondary);
      background: transparent;
      border: none;
      border-radius: var(--radius-full);
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
    }

    .flows-toggle-btn.active {
      background: var(--bg);
      color: var(--text);
      box-shadow: var(--shadow-sm);
    }

    .flows-content {
      display: none;
    }

    .flows-content.active {
      display: block;
    }

    .flows-video-preview {
      aspect-ratio: 9/16;
      max-width: 300px;
      margin: 0 auto;
      background: var(--surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .flows-video-placeholder {
      color: var(--text-muted);
      font-size: 14px;
      text-align: center;
      padding: 20px;
    }

    .flows-video-placeholder svg {
      width: 48px;
      height: 48px;
      margin-bottom: 12px;
      opacity: 0.5;
    }

    .flows-steps {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .flow-step {
      width: 140px;
      text-align: center;
    }

    .flow-step-card {
      aspect-ratio: 9/16;
      background: var(--surface);
      border-radius: var(--radius);
      border: 2px solid var(--border);
      margin-bottom: 8px;
      transition: all var(--transition);
    }

    .flow-step:hover .flow-step-card {
      border-color: var(--primary);
    }

    .flow-step-num {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
    }

    /* Tools Section */
    .features-tools {
      padding: 80px 0;
      background: var(--bg-secondary);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 24px;
    }

    .tool-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px;
      transition: all var(--transition);
    }

    .tool-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }

    .tool-icon {
      width: 48px;
      height: 48px;
      background: var(--primary);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .tool-icon svg {
      width: 24px;
      height: 24px;
      color: white;
    }

    .tool-card h3 {
      font-size: 18px;
      font-weight: 600;
      margin-bottom: 8px;
    }

    .tool-card p {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* Testimonials Section */
    .testimonials {
      padding: 80px 0;
      background: var(--bg);
      overflow: hidden;
    }

    .testimonials-track {
      display: flex;
      gap: 24px;
      animation: scroll-testimonials 30s linear infinite;
    }

    .testimonials-track:hover {
      animation-play-state: paused;
    }

    @keyframes scroll-testimonials {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .testimonial-card {
      flex-shrink: 0;
      width: 340px;
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 28px;
    }

    .testimonial-quote {
      font-size: 15px;
      line-height: 1.7;
      color: var(--text);
      margin-bottom: 20px;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      background: var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 14px;
      font-weight: 600;
    }

    .testimonial-info h4 {
      font-size: 14px;
      font-weight: 600;
    }

    .testimonial-info span {
      font-size: 13px;
      color: var(--text-muted);
    }

    .testimonials-row {
      margin-bottom: 24px;
    }

    .testimonials-row:nth-child(2) .testimonials-track {
      animation-direction: reverse;
    }

    /* CTA Section */
    .cta-section {
      padding: 100px 0;
      background: var(--bg-secondary);
      text-align: center;
    }

    .cta-section h2 {
      font-size: clamp(32px, 5vw, 44px);
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
    }

    .cta-section > .container > p {
      font-size: 18px;
      color: var(--text-secondary);
      margin-bottom: 32px;
    }

    .cta-buttons {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      margin-bottom: 64px;
      flex-wrap: wrap;
    }

    .app-marquee {
      overflow: hidden;
      padding: 24px 0;
    }

    .app-marquee-track {
      display: flex;
      gap: 48px;
      animation: scroll-marquee 20s linear infinite;
    }

    .app-marquee-track:nth-child(2) {
      animation-direction: reverse;
    }

    @keyframes scroll-marquee {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .app-icon {
      flex-shrink: 0;
      width: 48px;
      height: 48px;
      background: var(--surface);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      font-weight: 600;
      color: var(--text-secondary);
    }

    /* Footer */
    .footer {
      padding: 64px 0 32px;
      background: var(--bg);
      border-top: 1px solid var(--border);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand {
      max-width: 280px;
    }

    .footer-logo {
      font-size: 20px;
      font-weight: 700;
      color: var(--text);
      margin-bottom: 12px;
    }

    .footer-tagline {
      font-size: 14px;
      color: var(--text-secondary);
    }

    .footer-col h5 {
      font-size: 13px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .footer-links {
      list-style: none;
    }

    .footer-links li {
      margin-bottom: 10px;
    }

    .footer-links a {
      font-size: 14px;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition);
    }

    .footer-links a:hover {
      color: var(--text);
    }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 32px;
      border-top: 1px solid var(--border);
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-copyright {
      font-size: 13px;
      color: var(--text-muted);
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      font-size: 13px;
      color: var(--text-muted);
      text-decoration: none;
    }

    .footer-legal a:hover {
      color: var(--text);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 768px) {
      .nav-links {
        display: none;
      }

      .hero {
        padding: 60px 0 80px;
      }

      .stats-grid {
        grid-template-columns: 1fr;
        gap: 24px;
      }

      .stat-item {
        padding: 16px;
      }

      .trusted-logos {
        gap: 32px;
      }

      .filter-pills {
        justify-content: flex-start;
        overflow-x: auto;
        flex-wrap: nowrap;
        padding-bottom: 8px;
        -webkit-overflow-scrolling: touch;
      }

      .filter-pill {
        flex-shrink: 0;
      }

      .tools-grid {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }

      .testimonial-card {
        width: 280px;
      }

      .screenshot-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 480px) {
      .container {
        padding: 0 16px;
      }

      .hero-ctas {
        flex-direction: column;
      }

      .btn-lg {
        width: 100%;
      }

      .cta-buttons {
        flex-direction: column;
      }

      .cta-buttons .btn {
        width: 100%;
      }
    }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      .testimonials-track,
      .app-marquee-track {
        animation: none;
      }
    }

    /* Focus states */
    :focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
    }

    button:focus-visible,
    a:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
    }
  </style>
</head>
<body>
  <!-- Announcement Bar -->
  <div class="announcement">
    2025 ScreenVault Awards — Celebrating the best on the internet. <a href="#">Learn more</a>
  </div>

  <!-- Navigation -->
  <nav class="nav">
    <div class="container nav-inner">
      <a href="#" class="nav-logo">ScreenVault</a>
      <div class="nav-links">
        <a href="#" class="nav-link">Pricing</a>
        <a href="#" class="nav-link">Awards</a>
        <a href="#" class="nav-link">Log in</a>
      </div>
      <div class="nav-cta">
        <a href="#" class="btn btn-primary">Join for free</a>
      </div>
    </div>
  </nav>

  <!-- Hero Section -->
  <section class="hero">
    <div class="container">
      <div class="hero-badge">
        <span class="hero-badge-dot"></span>
        New: 200+ apps added this week
      </div>
      <h1>Discover real-world design inspiration.</h1>
      <p class="hero-subtitle">Featuring over 1,000 iOS & Web apps, and 200 sites — New content weekly.</p>
      <div class="hero-ctas">
        <a href="#" class="btn btn-primary btn-lg">Join for free</a>
        <a href="#" class="btn btn-secondary btn-lg">See our plans</a>
      </div>
      <p class="hero-note">No credit card required. Start exploring in seconds.</p>
    </div>
  </section>

  <!-- Trusted By Section -->
  <section class="trusted">
    <div class="container">
      <p class="trusted-label">Trusted by design teams at</p>
      <div class="trusted-logos">
        <span class="trusted-logo">Stripe</span>
        <span class="trusted-logo">Airbnb</span>
        <span class="trusted-logo">Google</span>
        <span class="trusted-logo">Meta</span>
        <span class="trusted-logo">Apple</span>
        <span class="trusted-logo">Microsoft</span>
        <span class="trusted-logo">Amazon</span>
        <span class="trusted-logo">Figma</span>
      </div>
    </div>
  </section>

  <!-- Stats Section -->
  <section class="stats" id="stats">
    <div class="container">
      <div class="stats-grid">
        <div class="stat-item">
          <div class="stat-number" data-target="1150">0</div>
          <div class="stat-label">apps</div>
        </div>
        <div class="stat-item">
          <div class="stat-number" data-target="615900">0</div>
          <div class="stat-label">screens</div>
