  <script>
    // Stats Counter Animation
    function animateCounter(element, target, duration = 2000) {
      const start = 0;
      const startTime = performance.now();

      function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease out cubic
        const easeOut = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(start + (target - start) * easeOut);

        element.textContent = current.toLocaleString();

        if (progress < 1) {
          requestAnimationFrame(update);
        } else {
          element.textContent = target.toLocaleString();
        }
      }

      requestAnimationFrame(update);
    }

    // Intersection Observer for stats animation
    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const counters = entry.target.querySelectorAll('.stat-number');
          counters.forEach((counter, index) => {
            setTimeout(() => {
              animateCounter(counter, parseInt(counter.dataset.target));
            }, index * 150);
          });
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    const statsSection = document.querySelector('.stats');
    if (statsSection) {
      statsObserver.observe(statsSection);
    }

    // Search Tabs
    const searchTabs = document.querySelectorAll('.search-tab');
    const featureContents = document.querySelectorAll('.feature-content');

    searchTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        const targetTab = tab.dataset.tab;

        searchTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        featureContents.forEach(content => {
          content.classList.toggle('active', content.dataset.content === targetTab);
        });
      });
    });

    // Filter Pills
    const filterPills = document.querySelectorAll('.filter-pill');

    filterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        filterPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
      });
    });

    // Flows Toggle
    const flowsToggleBtns = document.querySelectorAll('.flows-toggle-btn');
    const flowsContents = document.querySelectorAll('.flows-content');

    flowsToggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetFlow = btn.dataset.toggle;

        flowsToggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        flowsContents.forEach(content => {
          content.classList.toggle('active', content.dataset.flow === targetFlow);
        });
      });
    });

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });
  </script>
